class MinStack {
    stack;
    mins;
    constructor() {
        this.stack = [];
        this.mins = [];
    }
    push(x) {
        this.stack.push(x);
        this.mins.push(Math.min(this.getMin(), x));
    }
    pop() {
        this.stack.pop();
        this.mins.pop();
    }
    top() {
        return this.stack[this.stack.length - 1];
    }
    getMin() {
        return this.mins.length == 0 ? Infinity : this.mins[this.mins.length - 1];
    }
}
